net=model.load()
w=torch.tensor(np.load('contrast_c1_blocks.1.fc1_k10.npy')).float()
z=np.load('base.npz'); a0,F,C,xi=z['a0'],z['F'],z['C'],torch.tensor(z['xi']); N=len(C); c=torch.tensor(C)
# base target label: kNN on (a,c*3) w/ F[10]
from numpy.linalg import norm
X0=np.c_[a0,C*3]
def lab(a):
    X=np.c_[a,C*3]; L=[]
    for i in range(0,N,2000):
        d=((X[i:i+2000,None,:]-X0[None])**2).sum(-1); idx=np.argsort(d,1)[:,:7]
        L.append(F[10][idx].mean(1)>0.5)
    return np.concatenate(L)
T0=lab(a0); print('base target',T0.mean(), 'F10 rate',F[10].mean(), 'recall F8',F[8][T0].mean(),'ff8',F[8][~T0].mean())
# typical: distance to nearest base action
def offd(a):
    out=[]
    for i in range(0,N,2000):
        d=((a[i:i+2000,None,:]-a0[None])**2).sum(-1).min(1); out.append(np.sqrt(d))
    return np.concatenate(out)
def run(J,alpha,K,thr=0.0,r=0.45):
    u=torch.tensor([np.cos(J*np.pi/4),np.sin(J*np.pi/4)]).float()
    h=K[1]-K[0]; dv=-(alpha*r*20/h)*u
    x=xi.clone()
    for k in range(20):
        t=torch.full((N,),1-k/20)
        v,a=net.velocity(x,t,c,('blocks.1.fc1',),count=False)
        if K[0]<=k<K[1]:
            f=(a['blocks.1.fc1']@w+0.8966>thr); v=torch.where(f[:,None],v+dv,v)
        x=x-v/20
    a=x.numpy(); T=lab(a); mv=norm(a-a0,axis=1)>0.3; od=offd(a)>0.35
    return T[T0].mean(), T[~T0].mean(), mv[~T0].mean(), od.mean()
for K in [(8,11),(4,8),(0,4)]:
